<section class="comm-card"><div class="comm-head"><div><h2><?= $h($campaign_table_title??'Campaigns'); ?></h2><p class="muted">Track drafts, accepted sends and failures.</p></div><input type="search" id="comm-search" placeholder="Search campaigns" style="max-width:250px" aria-label="Search campaigns"></div><div class="comm-scroll"><table class="comm-table" id="comm-campaign-table"><thead><tr><th>Campaign</th><th>Status</th><th>Recipients</th><th>Accepted</th><th>Failed</th><th>Created</th><th>Actions</th></tr></thead><tbody><?php foreach($campaigns as $campaign):$schedule=$campaign->schedule??null;$waiting=$schedule && in_array($schedule['status'],array('scheduled','paused'),true);$displayStatus=$waiting?$schedule['status']:$campaign->status; ?><tr data-status="<?= $h($displayStatus); ?>"><td><b><?= $h($campaign->name); ?></b><br><span class="muted"><?= $h($campaign->subject??'SMS campaign'); ?></span></td><td><span class="comm-badge <?= $campaign->status==='sent'?'ok':'off'; ?>"><?= $h($displayStatus); ?></span><?php if($waiting):$due=(new DateTimeImmutable($schedule['scheduled_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Africa/Lagos')); ?><br><span class="mini"><?= $h($due->format('d M Y H:i')); ?> WAT · cap <?= number_format($schedule['budget_units']); ?> credits</span><?php if($schedule['last_error']): ?><p class="muted"><?= $status_text($schedule['last_error']); ?></p><?php endif; ?><?php endif; ?></td><td><?= (int)$campaign->audience_count; ?></td><td><?= (int)$campaign->sent_count; ?></td><td><?= (int)$campaign->failed_count; ?></td><td><?= $h($campaign->created_at); ?></td><td><div class="row"><?php if($waiting): ?><?= form_open('communications/cancel_schedule'); ?><input type="hidden" name="campaign_id" value="<?= (int)$campaign->id; ?>"><input type="hidden" name="channel" value="<?= $h($channel); ?>"><input type="hidden" name="screen" value="<?= $mobile?'mobile':'desktop'; ?>"><button class="btn secondary">Cancel schedule</button><?= form_close(); ?><?php endif; ?><?php if($campaign->status==='draft' && !$waiting): ?><button class="btn secondary" data-campaign="<?= (int)$campaign->id; ?>" data-test="1" <?= !$m['active']?'disabled':''; ?>>Test</button><?php endif; ?><?php if(!$waiting && in_array($campaign->status,array('draft','partial','sending'),true)): ?><button class="btn" data-campaign="<?= (int)$campaign->id; ?>" <?= !$m['active']?'disabled':''; ?>><?= $campaign->status==='draft'?'Review & send':'Resume'; ?></button><?php endif; ?><?php if($campaign->status!=='draft'): ?><a class="btn secondary" href="<?= $h($workspace_url('report',array('campaign'=>(int)$campaign->id))); ?>">View results</a><?php endif; ?></div><?php if(!$waiting && $campaign->status==='draft'): ?><details style="margin-top:8px"><summary>Schedule this draft</summary><?= form_open('communications/schedule_campaign'); ?><input type="hidden" name="campaign_id" value="<?= (int)$campaign->id; ?>"><input type="hidden" name="channel" value="<?= $h($channel); ?>"><input type="hidden" name="screen" value="<?= $mobile?'mobile':'desktop'; ?>"><label>Send at (West Africa Time)<input name="scheduled_at" type="datetime-local" required></label><label>Maximum credits<input name="budget_units" type="number" min="1" max="1000000" required></label><label class="choice"><input type="checkbox" required> I authorize this send within the cap.</label><button class="btn" style="margin-top:10px">Schedule campaign</button><?= form_close(); ?></details><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$campaigns): ?><p class="empty">Your first campaign starts here. Import contacts or choose a customer segment, then save a draft.</p><?php endif; ?><p class="muted"><?= $channel==='sms'?'Message acceptance comes from the sending network. Open campaign results for each recipient’s status.':'Reads and link clicks are counted from the delivered message itself. Open campaign results for each recipient.'; ?> <a href="<?= $h($workspace_url('report')); ?>">Campaign results →</a></p><div id="comm-result" role="status"></div></section>

<?php $this->load->view('messaging/campaign_billing'); ?>
